QPushButton*IndustryTopicPage::button(QHBoxLayout*layout,QString title,QString name,Action action){auto b=new QPushButton(title);b->setObjectName(name);b->setMinimumHeight(32);layout->addWidget(b);connect(b,&QPushButton::clicked,this,[this,b,action]{if(active&&isVisible()&&b->isVisible()&&b->isEnabled()&&window()->isActiveWindow())safe(action);});return b;}
void IndustryTopicPage::safe(Action action){try{action();}catch(const std::exception&e){if(state)state->setText(QString::fromUtf8(e.what()));}}
QString IndustryTopicPage::topic()const{return selected(topics);}QJsonArray IndustryTopicPage::selectedSources()const{QJsonArray ids;for(auto b:sourceChecks)if(b->isChecked())ids.append(b->property("sourceId").toString());return ids;}
QJsonObject IndustryTopicPage::config()const{QJsonArray list;for(auto line:urls->toPlainText().split(QRegularExpression("[\r\n]+")))if(!line.trimmed().isEmpty())list.append(line.trimmed());bool valid=false;int period=interval->text().toInt(&valid);need(valid,"周期分钟需整数");watchlistBackup::JsonGate{proposals->toPlainText()}.run();QJsonParseError error;auto proposalsDoc=QJsonDocument::fromJson(proposals->toPlainText().toUtf8(),&error);need(error.error==QJsonParseError::NoError&&proposalsDoc.isArray(),"候选需完整JSON数组");auto out=QJsonObject{{"enabled",enabled->isChecked()},{"intervalMinutes",period},{"sourceIds",selectedSources()},{"sourceUrls",list},{"proposals",proposalsDoc.array()},{"useAi",false}};return out;}
void IndustryTopicPage::changed(){if(filling)return;ack->setChecked(false);++epoch;runtime->cancelManual();}
void IndustryTopicPage::applySources(QJsonArray ids){QSet<QString>found;for(auto b:sourceChecks){auto id=b->property("sourceId").toString();found.insert(id);b->setChecked(ids.contains(id));}for(auto v:ids){auto id=v.toString();if(found.contains(id))continue;auto b=new QCheckBox("已配置来源缺失 · "+id+"\n保留身份；执行会报告缺源，不替换成其他资料。");b->setProperty("sourceId",id);b->setChecked(true);sourceLayout->addWidget(b);sourceChecks.append(b);connect(b,&QCheckBox::toggled,this,[this]{changed();});}}
void IndustryTopicPage::reload(){QScopedValueRollback<bool> rollback(filling);auto saved=topics->currentData().toString(),base=baselines->currentData().toString();auto material=rows();filling=true;baseRows=sourceCatalogue(material,true);choices(baselines,baseRows,base);Store store(directory+"/state.json");auto stateData=store.snapshot();expectedState=stateData.isEmpty()?QString():store.digest();topicRows=stateData.isEmpty()?QJsonArray():industryArchive::validate(stateData.value("archive").toString()).data.value("topics").toArray();choices(topics,topicRows,saved);for(auto b:sourceChecks){sourceLayout->removeWidget(b);delete b;}sourceChecks.clear();for(auto v:sourceCatalogue(material)){auto r=v.toObject();auto b=new QCheckBox(r.value("title").toString()+"\n"+r.value("sourceUrl").toString()+(r.value("hasFullText").toBool()?QString():QString(" · 缺正文")));b->setProperty("sourceId",r.value("id").toString());sourceLayout->addWidget(b);sourceChecks.append(b);connect(b,&QCheckBox::toggled,this,[this]{changed();});}baselineSha.clear();ack->setChecked(false);filling=false;loadTopic();reloadHistory();state->setText(topicRows.isEmpty()?"先查看并采用基线；历史任务保持停用。":"已读取完整执行状态。");}
void IndustryTopicPage::loadTopic(){QScopedValueRollback<bool> rollback(filling);if(topicRows.isEmpty()||topics->currentIndex()<0)return;filling=true;QJsonObject task{{"enabled",false},{"intervalMinutes",1440},{"sourceIds",QJsonArray{}},{"sourceUrls",QJsonArray{}},{"proposals",QJsonArray{}}};for(auto v:Store(directory+"/state.json").snapshot().value("tasks").toArray())if(v.toObject().value("topicId")==topic())task=v.toObject();enabled->setChecked(task.value("enabled").toBool());interval->setText(QString::number(task.value("intervalMinutes").toInt()));QStringList lines;for(auto v:task.value("sourceUrls").toArray())lines.append(v.toString());urls->setPlainText(lines.join('\n'));proposals->setPlainText(display(task.value("proposals")));auto ids=task.value("sourceIds").toArray();applySources(ids);ack->setChecked(false);filling=false;++epoch;runtime->cancelManual();}
void IndustryTopicPage::reloadHistory(){records->clear();auto list=history(Store(directory+"/state.json").snapshot(),topics->currentData().toString());for(int i=list.size()-1;i>=0;--i){auto r=list[i].toObject();auto item=new QListWidgetItem(r.value("label").toString(),records);item->setData(Qt::UserRole,r.value("key").toString());}}
void IndustryTopicPage::showMode(int value){mode=value;++epoch;toolbar->setVisible(value!=2);readerbar->setVisible(value==2);pages->setCurrentIndex(value);}
void IndustryTopicPage::open(QString key){auto snapshot=Store(directory+"/state.json").snapshot();fullText=reading(snapshot,key);exportText=key=="archive"?snapshot.value("archive").toString():key=="original"?snapshot.value("originalArchive").toString():fullText;exportName=key=="archive"||key=="original"?"产业主题完整档案.json":"产业主题完整阅读.txt";readingKey=key;segment=0;showMode(2);showReading();}
void IndustryTopicPage::showReading(){int count=std::max(1,int((fullText.size()+32767)/32768));segment=std::clamp(segment,0,count-1);int from=segment*32768,to=std::min(int(fullText.size()),from+32768);if(from>0&&fullText[from].isLowSurrogate())--from;if(to<fullText.size()&&fullText[to-1].isHighSurrogate())--to;reader->setPlainText(QString("第 %1 / %2 段 · 全文 %3 字符\n\n").arg(segment+1).arg(count).arg(fullText.size())+fullText.mid(from,to-from));}
QJsonObject IndustryTopicPage::draftValue()const{return {{"schema","native-industry-update-draft/v1"},{"baseline",baselines->currentData().toString()},{"topic",topics->currentData().toString()},{"sourceIds",selectedSources()},{"sourceUrls",urls->toPlainText()},{"proposals",proposals->toPlainText()},{"enabled",enabled->isChecked()},{"interval",interval->text()},{"mode",mode},{"readingKey",readingKey},{"segment",segment}};}
