void IndustryTopicPage::restoreState(QJsonObject shortState){watchlistBackup::keys(shortState,{"schema","sha256"});need(shortState.value("schema")=="native-f08-short/v1"&&shortState.value("sha256").isString(),"产业短状态无效");draftSha=shortState.value("sha256").toString();restore(draft.read(draftSha));}
void IndustryTopicPage::restore(QJsonObject d){QScopedValueRollback<bool> rollback(filling);filling=true;choices(baselines,baseRows,d.value("baseline").toString());choices(topics,topicRows,d.value("topic").toString());urls->setPlainText(d.value("sourceUrls").toString());proposals->setPlainText(d.value("proposals").toString());interval->setText(d.value("interval").toString());enabled->setChecked(d.value("enabled").toBool());auto ids=d.value("sourceIds").toArray();applySources(ids);ack->setChecked(false);baselineSha.clear();readingKey=d.value("readingKey").toString();segment=d.value("segment").toInt();mode=d.value("mode").toInt();if(mode==2){fullText=readingKey.startsWith("baseline:")?sourceBaseline(rows(),readingKey.mid(9)):reading(Store(directory+"/state.json").snapshot(),readingKey);exportText=readingKey=="archive"?Store(directory+"/state.json").snapshot().value("archive").toString():readingKey=="original"?Store(directory+"/state.json").snapshot().value("originalArchive").toString():fullText;exportName=readingKey=="archive"||readingKey=="original"||readingKey.startsWith("baseline:")?"产业主题完整档案.json":"产业主题完整阅读.txt";showReading();}filling=false;showMode(mode);}
void IndustryTopicPage::setActive(bool value){if(active==value)return;if(!value){runtime->cancelManual();++epoch;safe([this]{saveState();});}active=value;if(value){ack->setChecked(false);baselineSha.clear();}}
